def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    valid = rem >= 0
    if bins.size == 0:
        return np.array([], dtype=float)
    max_cap = np.max(bins)
    is_empty = np.isclose(bins, max_cap)
    scores = np.where(valid, 1.0 / (1.0 + rem**2), -1.0)
    scores = np.where(valid & is_empty, 0.001, scores)
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    return np.where(rem >= 0, 1.0 / (1.0 + rem), -1.0)
